fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    // Check if all input vectors have the same length
    if s1.len() != s2.len() || s1.len() != s3.len() {
        return Vec::new(); // or panic!("Input vectors must have the same length");
    }

    let n = s1.len();
    let mut res = Vec::with_capacity(3 * n); // Preallocate space for 3n elements

    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}